import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  registerRoot,
  Series,
} from "remotion";
import React, { useMemo } from "react";
import { Svg, Circle, Rect, Line, Polygon, Text } from "@remotion/svg";

// --- Interfaces & Types ---

interface PythagoreanCompositionProps {
  title: string;
}

interface TriangleProps {
  progress: number;
  showSquares: boolean;
  showGrid: boolean;
  sideA: number;
  sideB: number;
  sideC: number;
  colorA: string;
  colorB: string;
  colorC: string;
  labels: string[];
}

interface MathTextProps {
  children: React.ReactNode;
  fontSize?: number;
  color?: string;
  x?: number;
  y?: number;
  opacity?: number;
}

// --- Constants ---

const COLORS = {
  primary: "#3498db", // Side A
  secondary: "#e74c3c", // Side B
  accent: "#f1c40f", // Hypotenuse C
  text: "#2c3e50",
  bg: "#ecf0f1",
  grid: "#bdc3c7",
};

const TOTAL_FRAMES = 300;
const FPS = 30;

// --- Helper Components ---

const MathText: React.FC<MathTextProps> = ({
  children,
  fontSize = 40,
  color = COLORS.text,
  x = 0,
  y = 0,
  opacity = 1,
}) => {
  return (
    <div
      style={{
        fontFamily: "Georgia, serif",
        fontSize,
        color,
        position: "absolute",
        left: x,
        top: y,
        opacity,
        fontWeight: "bold",
        textAlign: "center",
        whiteSpace: "pre",
      }}
    >
      {children}
    </div>
  );
};

const TriangleDiagram: React.FC<TriangleProps> = ({
  progress,
  showSquares,
  showGrid,
  sideA,
  sideB,
  sideC,
  colorA,
  colorB,
  colorC,
  labels,
}) => {
  const centerX = 960;
  const centerY = 540;
  const scale = 80; // Pixels per unit

  // Coordinates for the right-angled triangle
  // Point 1: Right Angle (0,0) relative to center
  // Point 2: Top (0, -sideA)
  // Point 3: Right (sideB, 0)
  const p1 = { x: centerX, y: centerY };
  const p2 = { x: centerX, y: centerY - sideA * scale };
  const p3 = { x: centerX + sideB * scale, y: centerY };

  // Calculate square coordinates
  // Square on A (Left)
  const sqA = {
    x: p1.x - sideA * scale,
    y: p2.y,
    w: sideA * scale,
    h: sideA * scale,
  };

  // Square on B (Bottom)
  const sqB = {
    x: p1.x,
    y: p1.y,
    w: sideB * scale,
    h: sideB * scale,
  };

  // Square on C (Hypotenuse) - Requires rotation calculation
  // Angle of hypotenuse
  const angle = Math.atan2(sideA, sideB); // Radians
  const cLen = sideC * scale;

  // Helper to rotate point around p3
  const rotatePoint = (px: number, py: number, cx: number, cy: number, rad: number) => {
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);
    const nx = (cos * (px - cx)) + (sin * (py - cy)) + cx;
    const ny = (cos * (py - cy)) - (sin * (px - cx)) + cy;
    return { x: nx, y: ny };
  };

  // Construct square C points
  // Start at p2, go to p3. Vector is (sideB, sideA).
  // Normal vector is (-sideA, sideB).
  const cPoints = [
    { x: p2.x, y: p2.y },
    { x: p3.x, y: p3.y },
    rotatePoint(p3.x - sideA * scale, p3.y + sideB * scale, p3.x, p3.y, 0), // Simplified logic for visual
    rotatePoint(p2.x - sideA * scale, p2.y + sideB * scale, p2.x, p2.y, 0),
  ];

  // Correct logic for Hypotenuse Square points
  // Vector P2 -> P3
  const dx = p3.x - p2.x;
  const dy = p3.y - p2.y;
  // Perpendicular vector (-dy, dx)
  const p4 = { x: p3.x - dy, y: p3.y + dx };
  const p5 = { x: p2.x - dy, y: p2.y + dx };

  const squareScale = interpolate(progress, [0, 1], [0, 1]);

  return (
    <Svg
      width="1920"
      height="1080"
      viewBox="0 0 1920 1080"
      style={{ position: "absolute", top: 0, left: 0 }}
    >
      {/* Square on A */}
      {showSquares && (
        <g opacity={progress}>
          <Rect
            x={sqA.x}
            y={sqA.y}
            width={sqA.w * squareScale}
            height={sqA.h * squareScale}
            fill={colorA}
            fillOpacity={0.3}
            stroke={colorA}
            strokeWidth={4}
          />
          {showGrid && squareScale > 0.8 && (
             <>
               {/* Grid lines for A */}
               <Line x1={sqA.x} y1={sqA.y + sqA.h/2} x2={sqA.x + sqA.w} y2={sqA.y + sqA.h/2} stroke="white" strokeWidth="2" />
               <Line x1={sqA.x + sqA.w/2} y1={sqA.y} x2={sqA.x + sqA.w/2} y2={sqA.y + sqA.h} stroke="white" strokeWidth="2" />
             </>
          )}
        </g>
      )}

      {/* Square on B */}
      {showSquares && (
        <g opacity={progress}>
          <Rect
            x={sqB.x}
            y={sqB.y}
            width={sqB.w * squareScale}
            height={sqB.h * squareScale}
            fill={colorB}
            fillOpacity={0.3}
            stroke={colorB}
            strokeWidth={4}
          />
           {showGrid && squareScale > 0.8 && (
             <>
               {/* Grid lines for B (4x4) */}
               <Line x1={sqB.x + sqB.w/2} y1={sqB.y} x2={sqB.x + sqB.w/2} y2={sqB.y + sqB.h} stroke="white" strokeWidth="2" />
               <Line x1={sqB.x} y1={sqB.y + sqB.h/2} x2={sqB.x + sqB.w} y2={sqB.y + sqB.h/2} stroke="white" strokeWidth="2" />
             </>
          )}
        </g>
      )}

      {/* Square on C */}
      {showSquares && (
        <g opacity={progress}>
          <Polygon
            points={`${p2.x},${p2.y} ${p3.x},${p3.y} ${p4.x},${p4.y} ${p5.x},${p5.y}`}
            fill={colorC}
            fillOpacity={0.3}
            stroke={colorC}
            strokeWidth={4}
            // Simple scale transform from center of hypotenuse for animation effect
            transformOrigin={`${(p2.x + p3.x)/2},${(p2.y + p3.y)/2}`}
            scale={squareScale}
          />
           {showGrid && squareScale > 0.8 && (
             <>
               {/* Grid lines for C (5x5) - Simplified visual representation */}
               <Line x1={p5.x} y1={p5.y} x2={p3.x} y2={p3.y} stroke="white" strokeWidth="2" />
               <Line x1={p2.x} y1={p2.y} x2={p4.x} y2={p4.y} stroke="white" strokeWidth="2" />
             </>
          )}
        </g>
      )}

      {/* Main Triangle */}
      <Polygon
        points={`${p1.x},${p1.y} ${p2.x},${p2.y} ${p3.x},${p3.y}`}
        fill="white"
        stroke={COLORS.text}
        strokeWidth={5}
      />

      {/* Labels */}
      <Text x={p1.x - 40} y={p1.y - sideA * scale / 2} fontSize={40} fill={colorA} fontFamily="Arial" fontWeight="bold" textAnchor="end" alignmentBaseline="middle">
        {labels[0]}
      </Text>
      <Text x={p1.x + sideB * scale / 2} y={p1.y + 40} fontSize={40} fill={colorB} fontFamily="Arial" fontWeight="bold" textAnchor="middle" alignmentBaseline="hanging">
        {labels[1]}
      </Text>
      <Text x={(p2.x + p3.x) / 2 + 20} y={(p2.y + p3.y) / 2 - 20} fontSize={40} fill={colorC} fontFamily="Arial" fontWeight="bold" textAnchor="start">
        {labels[2]}
      </Text>
    </Svg>
  );
};

// --- Scene Components ---

