import React, { useMemo, useState, useEffect } from 'react';
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
  Composition,
  registerRoot,
} from 'remotion';

// --- Types & Interfaces ---

interface TriangleProps {
  progress: number;
  sideA: number;
  sideB: number;
  scale: number;
  showSquares: boolean;
  squareProgress: number;
}

interface LabelProps {
  x: number;
  y: number;
  text: string;
  color: string;
  fontSize: number;
  opacity: number;
}

// --- Constants ---

const COLORS = {
  primary: '#10B981', // Green for legs
  secondary: '#3B82F6', // Blue for secondary elements
  accent: '#EF4444', // Red for hypotenuse
  text: '#1F2937',
  bg: '#F3F4F6',
  squareA: 'rgba(16, 185, 129, 0.3)',
  squareB: 'rgba(16, 185, 129, 0.3)',
  squareC: 'rgba(239, 68, 68, 0.3)',
};

// --- Helper Components ---

const Label: React.FC<LabelProps> = ({ x, y, text, color, fontSize, opacity }) => {
  return (
    <text
      x={x}
      y={y}
      fill={color}
      fontSize={fontSize}
      fontWeight="bold"
      textAnchor="middle"
      dominantBaseline="middle"
      opacity={opacity}
      fontFamily="Georgia, serif"
    >
      {text}
    </text>
  );
};

const RightTriangle: React.FC<TriangleProps> = ({
  progress,
  sideA,
  sideB,
  scale,
  showSquares,
  squareProgress,
}) => {
  // Calculate coordinates based on centering the triangle
  // Triangle points: (0,0), (a,0), (0,b)
  // We center it visually in the SVG

  const a = sideA * scale;
  const b = sideB * scale;

  // Calculate hypotenuse length
  const c = Math.sqrt(a * a + b * b);

  // Offsets to center the triangle+bounds roughly in 1920x1080
  const offsetX = 960 - a / 2;
  const offsetY = 540 + b / 2;

  // Animation for drawing lines
  const drawProgress = Math.min(progress * 1.5, 1);

  // Points
  const p1 = { x: offsetX, y: offsetY }; // Bottom Left (Right Angle)
  const p2 = { x: offsetX + a, y: offsetY }; // Bottom Right
  const p3 = { x: offsetX, y: offsetY - b }; // Top Left

  return (
    <svg width="1920" height="1080" viewBox="0 0 1920 1080" style={{ overflow: 'visible' }}>
      {/* Square on A (Bottom) */}
      {showSquares && (
        <g opacity={squareProgress}>
          <rect
            x={p1.x}
            y={p1.y}
            width={a}
            height={a}
            fill={COLORS.squareA}
            stroke={COLORS.primary}
            strokeWidth="4"
          />
          <Label x={p1.x + a/2} y={p1.y + a/2} text="a²" color={COLORS.primary} fontSize={40} opacity={1} />
        </g>
      )}

      {/* Square on B (Left) */}
      {showSquares && (
        <g opacity={squareProgress}>
          <rect
            x={p1.x - b}
            y={p1.y - b}
            width={b}
            height={b}
            fill={COLORS.squareB}
            stroke={COLORS.primary}
            strokeWidth="4"
          />
          <Label x={p1.x - b/2} y={p1.y - b/2} text="b²" color={COLORS.primary} fontSize={40} opacity={1} />
        </g>
      )}

      {/* Square on C (Hypotenuse) - Complex Geometry */}
      {showSquares && (
        <g opacity={squareProgress}>
           {/* 
             To draw a square on the hypotenuse, we need to rotate the coordinate system.
             The hypotenuse goes from (a,0) to (0,b) relative to p1.
             Angle is atan2(-b, a).
           */}
           <g transform={`translate(${p2.x}, ${p2.y}) rotate(${Math.atan2(-b, a) * 180 / Math.PI})`}>
             <rect
               x={0}
               y={0}
               width={c}
               height={c}
               fill={COLORS.squareC}
               stroke={COLORS.accent}
               strokeWidth="4"
             />
             <text
               x={c/2}
               y={c/2}
               fill={COLORS.accent}
               fontSize={40}
               fontWeight="bold"
               textAnchor="middle"
               dominantBaseline="middle"
               transform={`rotate(${-Math.atan2(-b, a) * 180 / Math.PI}, ${c/2}, ${c/2})`}
               fontFamily="Georgia, serif"
             >
               c²
             </text>
           </g>
        </g>
      )}

      {/* The Triangle */}
      <g>
        {/* Side A */}
        <line
          x1={p1.x}
          y1={p1.y}
          x2={p1.x + a * drawProgress}
          y2={p1.y}
          stroke={COLORS.primary}
          strokeWidth="8"
          strokeLinecap="round"
        />
        {/* Side B */}
        <line
          x1={p1.x}
          y1={p1.y}
          x2={p1.x}
          y2={p1.y - b * drawProgress}
          stroke={COLORS.primary}
          strokeWidth="8"
          strokeLinecap="round"
        />
        {/* Side C (Hypotenuse) */}
        {progress > 0.5 && (
          <line
            x1={p1.x + a}
            y1={p1.y}
            x2={p1.x}
            y2={p1.y - b}
            stroke={COLORS.accent}
            strokeWidth="8"
            strokeLinecap="round"
            opacity={interpolate(progress, [0.5, 0.8], [0, 1])}
          />
        )}

        {/* Right Angle Symbol */}
        {progress > 0.3 && (
          <path
            d={`M ${p1.x} ${p1.y - 40} L ${p1.x + 40} ${p1.y - 40} L ${p1.x + 40} ${p1.y}`}
            stroke={COLORS.text}
            strokeWidth="4"
            fill="none"
            opacity={interpolate(progress, [0.3, 0.6], [0, 1])}
          />
        )}

        {/* Labels */}
        <Label x={p1.x + a/2} y={p1.y + 40} text="a" color={COLORS.primary} fontSize={48} opacity={progress} />
        <Label x={p1.x - 40} y={p1.y - b/2} text="b" color={COLORS.primary} fontSize={48} opacity={progress} />
        {progress > 0.5 && (
           <Label 
             x={(p1.x + p2.x + p3.x)/3 + 40} 
             y={(p1.y + p2.y + p3.y)/3 - 40} 
             text="c" 
             color={COLORS.accent} 
             fontSize={48} 
             opacity={interpolate(progress, [0.5, 0.8], [0, 1])} 
           />
        )}
      </g>
    </svg>
  );
};

