const TaylorGraph: React.FC<GraphProps> = ({ n, frame }) => {
  const width = 800;
  const height = 400;
  const centerX = width / 2;
  const centerY = height / 2 + 100;
  const scaleX = 80; // pixels per unit
  const scaleY = 80;

  // Function f(x) = e^x
  const f = (x: number) => Math.exp(x);

  // Taylor Polynomial P_n(x) for e^x at a=0
  const P = (x: number, degree: number) => {
    let sum = 0;
    for (let i = 0; i <= degree; i++) {
      sum += Math.pow(x, i) / factorial(i);
    }
    return sum;
  };

  const factorial = (n: number): number => {
    if (n === 0) return 1;
    let result = 1;
    for (let i = 1; i <= n; i++) result *= i;
    return result;
  };

  // Generate path data
  const generatePath = (func: (x: number) => number, color: string, dashed = false) => {
    let path = `M`;
    const step = 0.1;
    // Draw from x = -3 to 3
    for (let x = -3.5; x <= 3.5; x += step) {
      const y = func(x);
      const px = centerX + x * scaleX;
      const py = centerY - y * scaleY;
      path += `${px},${py} `;
    }
    return (
      <path
        d={path}
        stroke={color}
        strokeWidth={3}
        fill="none"
        strokeDasharray={dashed ? "5,5" : "none"}
      />
    );
  };

  return (
    <svg width={width} height={height} style={{ background: "white", borderRadius: 10 }}>
      {/* Grid */}
      <line x1={0} y1={centerY} x2={width} y2={centerY} stroke={COLORS.grid} strokeWidth={2} />
      <line x1={centerX} y1={0} x2={centerX} y2={height} stroke={COLORS.grid} strokeWidth={2} />

      {/* Actual Function e^x */}
      {generatePath(f, COLORS.primary)}

      {/* Taylor Polynomial */}
      {generatePath((x) => P(x, n), COLORS.secondary)}

      {/* Legend */}
      <text x={20} y={30} fontSize={20} fill={COLORS.primary} fontFamily={FONT_FAMILY}>
        f(x) = eˣ
      </text>
      <text x={20} y={60} fontSize={20} fill={COLORS.secondary} fontFamily={FONT_FAMILY}>
