import React, { useMemo, useState, useEffect } from 'react';
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
  Composition,
  registerRoot,
} from 'remotion';

// --- Types & Interfaces ---

interface Point {
  x: number;
  y: number;
}

interface GraphProps {
  order: number; // 0 to 5
  progress: number; // 0 to 1 for animation within scene
  showTarget: boolean;
  center: number; // The 'a' value
}

interface FormulaDisplayProps {
  latex: string;
  subtext?: string;
  highlight?: boolean;
  opacity?: number;
}

// --- Constants & Config ---

const VIDEO_CONFIG = {
  width: 1920,
  height: 1080,
  fps: 30,
  durationInFrames: 300,
};

const COLORS = {
  background: '#0f172a', // Slate 900
  text: '#f8fafc', // Slate 50
  primary: '#3B82F6', // Blue 500 (Target Function)
  secondary: '#F59E0B', // Amber 500 (Polynomial)
  accent: '#10B981', // Emerald 500 (Success/Highlight)
  grid: '#334155', // Slate 700
  axis: '#94a3b8', // Slate 400
};

const GRAPH_CONFIG = {
  scaleX: 100, // pixels per unit
  scaleY: 200, // pixels per unit
  originX: VIDEO_CONFIG.width / 2,
  originY: VIDEO_CONFIG.height / 2 + 100,
};

// --- Helper Functions ---

// Target Function: sin(x)
const f = (x: number) => Math.sin(x);

// Derivatives of sin(x) at a=0
// sin(0) = 0, cos(0) = 1, -sin(0) = 0, -cos(0) = -1...
const getDerivativeAtZero = (n: number): number => {
  const mod = n % 4;
  if (mod === 0) return 0;
  if (mod === 1) return 1;
  if (mod === 2) return 0;
  return -1;
};

// Taylor Polynomial Calculation
const taylorPoly = (x: number, order: number): number => {
  let sum = 0;
  for (let n = 0; n <= order; n++) {
    const deriv = getDerivativeAtZero(n);
    const coeff = deriv / factorial(n);
    sum += coeff * Math.pow(x, n);
  }
  return sum;
};

const factorial = (n: number): number => {
  if (n === 0 || n === 1) return 1;
  let result = 1;
  for (let i = 2; i <= n; i++) result *= i;
  return result;
};

// --- Visualization Components ---

const Axis: React.FC = () => {
  const { width, height } = VIDEO_CONFIG;
  const { originX, originY } = GRAPH_CONFIG;

  return (
    <g>
      {/* X Axis */}
      <line
        x1="0"
        y1={originY}
        x2={width}
        y2={originY}
        stroke={COLORS.axis}
        strokeWidth="2"
      />
      {/* Y Axis */}
      <line
        x1={originX}
        y1="0"
        x2={originX}
        y2={height}
        stroke={COLORS.axis}
        strokeWidth="2"
      />
      {/* Ticks */}
      {[...Array(10)].map((_, i) => {
        const x = originX + i * GRAPH_CONFIG.scaleX;
        const negX = originX - i * GRAPH_CONFIG.scaleX;
        return (
          <g key={i}>
            <line x1={x} y1={originY - 5} x2={x} y2={originY + 5} stroke={COLORS.axis} />
            <line x1={negX} y1={originY - 5} x2={negX} y2={originY + 5} stroke={COLORS.axis} />
          </g>
        );
      })}
    </g>
  );
};

const FunctionCurve: React.FC<{ color: string; order?: number; dashed?: boolean }> = ({
  color,
  order,
  dashed = false,
}) => {
  const points: Point[] = [];
  const { width } = VIDEO_CONFIG;
  const { scaleX, originX, originY } = GRAPH_CONFIG;

  // Generate points from left edge to right edge
  for (let px = 0; px <= width; px += 5) {
    const x = (px - originX) / scaleX;
    const y = order !== undefined ? taylorPoly(x, order) : f(x);
    const py = originY - y * GRAPH_CONFIG.scaleY;
    points.push({ x: px, y: py });
  }

  const pathData = `M ${points.map((p) => `${p.x},${p.y}`).join(' L ')}`;

  return (
    <path
      d={pathData}
      stroke={color}
      strokeWidth="4"
      fill="none"
      strokeDasharray={dashed ? "10, 10" : "none"}
    />
  );
};

const GraphContainer: React.FC<GraphProps> = ({ order, progress, showTarget, center }) => {
  return (
    <svg
      width={VIDEO_CONFIG.width}
      height={VIDEO_CONFIG.height}
      style={{ backgroundColor: COLORS.background }}
    >
      <Axis />

      {/* Target Function (Sin(x)) */}
      {showTarget && (
        <g opacity={showTarget ? 1 : 0}>
          <FunctionCurve color={COLORS.primary} />
          <text
            x={VIDEO_CONFIG.width - 150}
            y={100}
            fill={COLORS.primary}
