      )}

      {/* Taylor Polynomial */}
      <FunctionCurve color={COLORS.secondary} order={order} dashed={order === 0} />

      {/* Center Point Marker */}
      <circle
        cx={GRAPH_CONFIG.originX}
        cy={GRAPH_CONFIG.originY}
        r="6"
        fill={COLORS.accent}
      />
      <text
        x={GRAPH_CONFIG.originX + 15}
        y={GRAPH_CONFIG.originY + 25}
        fill={COLORS.text}
        fontSize="20"
        fontFamily="sans-serif"
      >
        a = {center}
      </text>

      {/* Order Indicator */}
      <text
        x={50}
        y={100}
        fill={COLORS.secondary}
        fontSize="32"
        fontWeight="bold"
        fontFamily="sans-serif"
      >
        Order n = {order}
      </text>
    </svg>
  );
};

const FormulaDisplay: React.FC<FormulaDisplayProps> = ({ latex, subtext, highlight, opacity = 1 }) => {
  return (
    <div
      style={{
        position: 'absolute',
        bottom: 100,
        left: 0,
        right: 0,
        textAlign: 'center',
        opacity,
        transform: `scale(${highlight ? 1.1 : 1})`,
        transition: 'transform 0.3s ease',
      }}
    >
      <div
        style={{
          fontSize: '48px',
          color: highlight ? COLORS.accent : COLORS.text,
          fontFamily: 'Georgia, serif',
          marginBottom: '20px',
          textShadow: '0 2px 10px rgba(0,0,0,0.5)',
        }}
      >
        {latex}
