const ParabolaGraph: React.FC<ParabolaProps> = ({
  progress,
  showVertex = false,
  showRoots = false,
}) => {
  const width = 600;
  const height = 400;
  const centerX = width / 2;
  const centerY = height - 50; // Origin near bottom
  const scale = 40; // Pixels per unit

  // Parabola parameters: y = x^2 - 4 (roots at -2, 2, vertex at 0, -4)
  // We shift it visually to match the "vertex shift" concept later
  const vertexX = interpolate(progress, [0, 1], [0, -2]); // Shift vertex left
  const vertexY = -4;

  const generatePath = () => {
    let d = "";
    for (let x = -5; x <= 5; x += 0.1) {
      const realX = x + vertexX;
      const y = realX * realX - 4; // Simple parabola logic for visualization
      const px = centerX + x * scale;
      const py = centerY - y * scale;
      d += `${x === -5 ? "M" : "L"} ${px} ${py} `;
    }
    return d;
  };

  const axisOpacity = interpolate(progress, [0, 0.2], [0, 1]);

  return (
    <Svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      style={{ overflow: "visible" }}
    >
      {/* Grid */}
      <g opacity={0.2}>
        {[...Array(11)].map((_, i) => (
          <Line
            key={i}
            x1={i * 60}
            y1={0}
            x2={i * 60}
            y2={height}
            stroke={COLORS.primary}
            strokeWidth="1"
          />
        ))}
        {[...Array(9)].map((_, i) => (
          <Line
            key={i}
            x1={0}
            y1={i * 50}
            x2={width}
            y2={i * 50}
            stroke={COLORS.primary}
            strokeWidth="1"
          />
        ))}
      </g>

      {/* Axes */}
      <g opacity={axisOpacity}>
        <Line
          x1={0}
          y1={centerY}
          x2={width}
          y2={centerY}
          stroke={COLORS.primary}
          strokeWidth="2"
        />{" "}
        {/* X Axis */}
        <Line
          x1={centerX}
          y1={0}
          x2={centerX}
          y2={height}
          stroke={COLORS.primary}
          strokeWidth="2"
        />{" "}
        {/* Y Axis */}
      </g>

      {/* Parabola */}
      <Path d={generatePath()} fill="none" stroke={COLORS.secondary} strokeWidth="4" />

      {/* Vertex Highlight */}
      {showVertex && (
        <Circle
          cx={centerX + vertexX * scale}
          cy={centerY - vertexY * scale}
          r="6"
          fill={COLORS.accent}
        />
      )}

      {/* Roots Highlight */}
      {showRoots && (
        <>
          <Circle
            cx={centerX - 2 * scale}
            cy={centerY}
            r="6"
            fill={COLORS.primary}
          />
          <Circle
            cx={centerX + 2 * scale}
            cy={centerY}
            r="6"
            fill={COLORS.primary}
          />
        </>
      )}
    </Svg>
  );
};

