const Latex: React.FC<{ children: string; color?: string; size?: number }> = ({ children, color = '#1F2937', size = 32 }) => {
  // Simple parser for basic math formatting
  const formatMath = (text: string) => {
    let formatted = text
      .replace(/\^\{([^}]+)\}/g, '<sup>$1</sup>') // x^{2} -> x<sup>2</sup>
      .replace(/\^(\d)/g, '<sup>$1</sup>') // x^2 -> x<sup>2</sup>
      .replace(/_\{([^}]+)\}/g, '<sub>$1</sub>') // x_{i} -> x<sub>i</sub>
      .replace(/_/g, '') // Remove remaining underscores if any
      .replace(/\\pm/g, '±')
      .replace(/\\sqrt/g, '√')
      .replace(/\\frac\{([^}]+)\}\{([^}]+)\}/g, '<span style="display:inline-block; vertical-align:middle; text-align:center;"><span style="display:block; border-bottom:1px solid currentColor; padding:0 2px;">$1</span><span style="display:block; padding:0 2px;">$2</span></span>');

    return <span dangerouslySetInnerHTML={{ __html: formatted }} />;
  };

  return (
    <div style={{ fontFamily: 'Times New Roman, serif', fontSize: size, color, fontWeight: 'bold' }}>
      {formatMath(children)}
    </div>
  );
};

