const ParabolaGraph: React.FC<GraphProps> = ({ a, b, c, progress, showRoots = false, showAxis = false }) => {
  const width = 600;
  const height = 400;
  const centerX = width / 2;
  const centerY = height / 2;
  const scale = 40; // pixels per unit

  // Calculate vertex
  const h = -b / (2 * a);
  const k = c - (b * b) / (4 * a);

  // Calculate roots
  const discriminant = b * b - 4 * a * c;
  const root1 = (-b + Math.sqrt(discriminant)) / (2 * a);
  const root2 = (-b - Math.sqrt(discriminant)) / (2 * a);

  // Generate path data
  const pathData = useMemo(() => {
    let d = '';
    const startX = -centerX / scale;
    const endX = centerX / scale;
    const step = 0.1;

    for (let x = startX; x <= endX; x += step) {
      const y = a * x * x + b * x + c;
      const px = centerX + x * scale;
      const py = centerY - y * scale;
      d += `${x === startX ? 'M' : 'L'} ${px},${py} `;
    }
    return d;
  }, [a, b, c, centerX, centerY, scale]);

  // Axis of symmetry position
  const axisX = centerX + h * scale;

  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ overflow: 'visible' }}>
      {/* Grid */}
      <defs>
        <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
          <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#e5e7eb" strokeWidth="1" />
        </pattern>
      </defs>
      <rect width={width} height={height} fill="url(#grid)" />

      {/* Axes */}
      <line x1="0" y1={centerY} x2={width} y2={centerY} stroke="#9CA3AF" strokeWidth="2" />
      <line x1={centerX} y1="0" x2={centerX} y2={height} stroke="#9CA3AF" strokeWidth="2" />

      {/* Axis of Symmetry */}
      {showAxis && (
        <line
          x1={axisX}
          y1="0"
          x2={axisX}
          y2={height}
          stroke="#F59E0B"
          strokeWidth="2"
          strokeDasharray="5,5"
          style={{ opacity: progress }}
        />
      )}

      {/* Parabola */}
      <path
        d={pathData}
        fill="none"
        stroke="#8B5CF6"
        strokeWidth="4"
        strokeLinecap="round"
        style={{
          filter: 'drop-shadow(0px 4px 6px rgba(139, 92, 246, 0.4))',
          strokeDasharray: 2000,
          strokeDashoffset: 2000 * (1 - progress),
          transition: 'stroke-dashoffset 0.1s linear',
        }}
      />

      {/* Roots */}
      {showRoots && discriminant >= 0 && (
        <>
          <circle cx={centerX + root1 * scale} cy={centerY} r="6" fill="#10B981" />
          <circle cx={centerX + root2 * scale} cy={centerY} r="6" fill="#10B981" />
        </>
      )}

      {/* Vertex */}
      <circle cx={centerX + h * scale} cy={centerY - k * scale} r="6" fill="#EF4444" />
    </svg>
  );
};

