const BellCurve: React.FC<BellCurveProps> = ({
  mean,
  stdDev,
  height,
  width,
  color = COLORS.curve,
  fillOpacity = 0,
  showArea,
}) => {
  const generatePath = (min: number, max: number, closePath = false) => {
    const points: Point[] = [];
    const steps = 100;
    const range = max - min;

    // Gaussian function
    const gaussian = (x: number) => {
      const numerator = Math.exp(-0.5 * Math.pow((x - mean) / stdDev, 2));
      return (height * 0.8) * numerator; // Scale to 80% of container height
    };

    for (let i = 0; i <= steps; i++) {
      const x = min + (range * i) / steps;
      const y = height - gaussian(x) - 20; // 20px padding bottom
      points.push({ x, y });
    }

    if (points.length === 0) return "";

    let d = `M ${points[0].x} ${points[0].y}`;
    for (let i = 1; i < points.length; i++) {
      d += ` L ${points[i].x} ${points[i].y}`;
    }

    if (closePath) {
      d += ` L ${points[points.length - 1].x} ${height}`;
      d += ` L ${points[0].x} ${height}`;
      d += " Z";
    }

    return d;
  };

  // Define visible range (e.g., -4 to +4 standard deviations)
  const minX = mean - 4 * stdDev;
  const maxX = mean + 4 * stdDev;

  const mainPath = generatePath(minX, maxX);
  const areaPath = showArea ? generatePath(showArea.min, showArea.max, true) : "";

  return (
