  useVideoConfig,
  interpolate,
  spring,
  Sequence,
  staticFile,
} from 'remotion';

// --- Types & Interfaces ---

interface BellCurveProps {
  progress: number;
  showMean: boolean;
  showSigma: number; // 0 to 3
  shadeLevel: number; // 0 to 3
  color: string;
}

interface LabelProps {
  text: string;
  x: number;
  y: number;
  opacity: number;
  fontSize?: number;
  color?: string;
  align?: 'left' | 'center' | 'right';
}

// --- Helper Components ---

const Label: React.FC<LabelProps> = ({ text, x, y, opacity, fontSize = 40, color = '#ffffff', align = 'center' }) => {
  return (
    <div
      style={{
        position: 'absolute',
        left: x,
        top: y,
        opacity,
        color,
        fontSize: `${fontSize}px`,
        fontWeight: 'bold',
        fontFamily: 'Arial, sans-serif',
        transform: align === 'center' ? 'translate(-50%, -50%)' : 'translate(0, -50%)',
        textAlign: align,
        textShadow: '0 2px 4px rgba(0,0,0,0.5)',
        whiteSpace: 'nowrap',
      }}
    >
      {text}
    </div>
  );
};

const BellCurve: React.FC<BellCurveProps> = ({ progress, showMean, showSigma, shadeLevel, color }) => {
  const width = 1000;
  const height = 500;
  const centerX = width / 2;
  const centerY = height - 50; // Bottom padding
  const scaleX = 100; // Pixels per standard deviation
  const scaleY = 350; // Height scaling

  // Gaussian function: y = e^(-0.5 * x^2)
  // We map x from -3.5 to 3.5 standard deviations
  const points = useMemo(() => {
    const pts: string[] = [];
    const steps = 100;
    for (let i = 0; i <= steps; i++) {
      const xNorm = -3.5 + (i / steps) * 7; // -3.5 to 3.5
      const yNorm = Math.exp(-0.5 * xNorm * xNorm);

      const x = centerX + xNorm * scaleX;
      const y = centerY - yNorm * scaleY;
      pts.push(`${x},${y}`);
    }
    return pts.join(' ');
  }, [centerX, centerY, scaleX, scaleY]);

  // Generate path for shaded regions
  const getShadedPath = (sigmas: number) => {
    const steps = 60;
    let path = `M ${centerX - sigmas * scaleX},${centerY} `;

    for (let i = 0; i <= steps; i++) {
      const xNorm = -sigmas + (i / steps) * (sigmas * 2);
      const yNorm = Math.exp(-0.5 * xNorm * xNorm);
      const x = centerX + xNorm * scaleX;
      const y = centerY - yNorm * scaleY;
      path += `L ${x},${y} `;
    }
    path += `L ${centerX + sigmas * scaleX},${centerY} Z`;
    return path;
  };

  // Calculate opacity for shading based on scene progress
  const getShadeOpacity = (level: number) => {
    if (shadeLevel < level) return 0;
    if (shadeLevel > level) return 0.6; // Fully visible
    // Transitioning
    return interpolate(shadeLevel, [level - 0.5, level], [0, 0.6], { extrapolateRight: 'clamp' });
  };

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      style={{ overflow: 'visible' }}
    >
      {/* Shaded Regions */}
      {shadeLevel >= 1 && (
        <path
          d={getShadedPath(1)}
          fill={color}
          opacity={getShadeOpacity(1)}
        />
      )}
      {shadeLevel >= 2 && (
        <path
          d={getShadedPath(2)}
          fill={color}
          opacity={getShadeOpacity(2)}
        />
      )}
      {shadeLevel >= 3 && (
        <path
          d={getShadedPath(3)}
          fill={color}
          opacity={getShadeOpacity(3)}
        />
      )}

      {/* Main Curve Line */}
      <polyline
        points={points}
        fill="none"
        stroke="#ffffff"
        strokeWidth="4"
        strokeOpacity={interpolate(progress, [0, 0.2], [0, 1])}
        strokeDasharray={points}
        strokeDashoffset={points} // Initial state for animation if needed, simplified here
      />

      {/* Mean Line */}
      {showMean && (
        <line
          x1={centerX}
          y1={centerY}
          x2={centerX}
          y2={centerY - scaleY * 0.99} // Top of curve
          stroke="#ffffff"
          strokeWidth="2"
          strokeDasharray="5,5"
          opacity={interpolate(progress, [0.2, 0.4], [0, 1])}
        />
      )}

      {/* Sigma Markers (Vertical Lines) */}
      {[1, 2, 3].map((sig) => {
        if (sig > showSigma) return null;
        const xPos = centerX + sig * scaleX;
        const xNeg = centerX - sig * scaleX;
        const yPos = centerY - Math.exp(-0.5 * sig * sig) * scaleY;

        const opacity = interpolate(showSigma, [sig - 0.5, sig], [0, 0.8]);

        return (
          <g key={sig} opacity={opacity}>
            <line x1={xPos} y1={centerY} x2={xPos} y2={yPos} stroke="#cbd5e1" strokeWidth="2" />
            <line x1={xNeg} y1={centerY} x2={xNeg} y2={yPos} stroke="#cbd5e1" strokeWidth="2" />
          </g>
        );
      })}
    </svg>
  );
};

