import React, { useMemo, useState, useEffect, useCallback } from 'react';
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
  Composition,
  registerRoot,
  Audio,
} from 'remotion';

// --- Interfaces & Types ---

interface Vector2D {
  x: number;
  y: number;
}

interface Matrix2x2 {
  a: number;
  b: number;
  c: number;
  d: number;
}

interface SceneProps {
  progress: number;
}

// --- Constants & Config ---

const COLORS = {
  primary: '#8B5CF6', // Purple
  secondary: '#EC4899', // Pink
  accent: '#10B981', // Green
  background: '#111827', // Dark Gray
  text: '#F3F4F6', // White/Light Gray
  grid: '#374151', // Grid lines
  eigen1: '#F59E0B', // Amber for Eigenvector 1
  eigen2: '#3B82F6', // Blue for Eigenvector 2
};

const FONT_FAMILY = 'Georgia, serif';

// --- Helper Components ---

const Latex: React.FC<{ children: React.ReactNode; size?: number; color?: string }> = ({
  children,
  size = 48,
  color = COLORS.text,
}) => {
  return (
    <div
      style={{
        fontFamily: FONT_FAMILY,
        fontSize: `${size}px`,
        color,
        textAlign: 'center',
        fontWeight: 'bold',
        textShadow: '0 2px 4px rgba(0,0,0,0.5)',
      }}
    >
      {children}
    </div>
  );
};

const MatrixDisplay: React.FC<{ matrix: Matrix2x2; label?: string }> = ({ matrix, label }) => {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '10px' }}>
      {label && <span style={{ color: COLORS.text, fontSize: 24 }}>{label}</span>}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '10px 20px',
          padding: '15px',
          border: `2px solid ${COLORS.primary}`,
          borderRadius: '8px',
          background: 'rgba(255,255,255,0.05)',
        }}
      >
        <span style={{ color: COLORS.text, fontSize: 32 }}>{matrix.a}</span>
        <span style={{ color: COLORS.text, fontSize: 32 }}>{matrix.b}</span>
        <span style={{ color: COLORS.text, fontSize: 32 }}>{matrix.c}</span>
        <span style={{ color: COLORS.text, fontSize: 32 }}>{matrix.d}</span>
      </div>
    </div>
  );
};

// --- Visualization Components ---

const GridTransform: React.FC<{
  progress: number;
  matrix: Matrix2x2;
  showEigen?: boolean;
  eigenVectors?: Vector2D[];
}> = ({ progress, matrix, showEigen = false, eigenVectors = [] }) => {
  const size = 400;
  const center = size / 2;
  const scale = 40; // Pixels per unit

  // Interpolate matrix values for animation
  const currentMatrix = {
    a: interpolate(progress, [0, 1], [1, matrix.a]),
    b: interpolate(progress, [0, 1], [0, matrix.b]),
    c: interpolate(progress, [0, 1], [0, matrix.c]),
    d: interpolate(progress, [0, 1], [1, matrix.d]),
  };

  const transformPoint = (x: number, y: number) => {
    // Apply matrix
    const nx = currentMatrix.a * x + currentMatrix.b * y;
    const ny = currentMatrix.c * x + currentMatrix.d * y;
    return { x: nx, y: ny };
  };

  const toScreen = (x: number, y: number) => {
    return {
      x: center + x * scale,
      y: center - y * scale, // Flip Y for screen coords
    };
  };

  // Generate Grid Lines
  const lines = [];
  for (let i = -5; i <= 5; i++) {
    // Vertical lines
    let vPath = `M ${toScreen(i, -5).x} ${toScreen(i, -5).y}`;
    for (let j = -4; j <= 5; j++) {
      const p = transformPoint(i, j);
      const sp = toScreen(p.x, p.y);
      vPath += ` L ${sp.x} ${sp.y}`;
    }
    lines.push(<path key={`v${i}`} d={vPath} stroke={COLORS.grid} strokeWidth="1" fill="none" />);

    // Horizontal lines
    let hPath = `M ${toScreen(-5, i).x} ${toScreen(-5, i).y}`;
    for (let j = -4; j <= 5; j++) {
      const p = transformPoint(j, i);
      const sp = toScreen(p.x, p.y);
      hPath += ` L ${sp.x} ${sp.y}`;
    }
    lines.push(<path key={`h${i}`} d={hPath} stroke={COLORS.grid} strokeWidth="1" fill="none" />);
  }

  // Eigenvectors
  const eigenArrows = eigenVectors.map((ev, idx) => {
    const color = idx === 0 ? COLORS.eigen1 : COLORS.eigen2;
    const transformed = transformPoint(ev.x, ev.y);
    const start = toScreen(0, 0);
    const end = toScreen(transformed.x, transformed.y);

    // Only show if progress is significant
    if (progress < 0.1) return null;

    return (
      <g key={idx}>
        <line
          x1={start.x}
          y1={start.y}
          x2={end.x}
          y2={end.y}
          stroke={color}
          strokeWidth="4"
          strokeDasharray={idx === 0 ? "0" : "10,5"}
        />
        <circle cx={end.x} cy={end.y} r="6" fill={color} />
      </g>
    );
  });

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ overflow: 'visible' }}>
      {/* Background */}
      <rect width={size} height={size} fill="rgba(0,0,0,0.3)" rx="10" />

      {/* Grid */}
      <g transform={`translate(0,0)`}>{lines}</g>

      {/* Axes */}
      <line x1="0" y1={center} x2={size} y2={center} stroke={COLORS.text} strokeWidth="2" opacity="0.5" />
      <line x1={center} y1="0" x2={center} y2={size} stroke={COLORS.text} strokeWidth="2" opacity="0.5" />

      {/* Eigenvectors */}
      {showEigen && eigenArrows}
    </svg>
  );
};

