             flexDirection: 'column', 
             gap: 20, 
             opacity: interpolate(progress, [0.7, 1], [0, 1]) 
           }}>
             <div style={{ color: COLORS.text, fontSize: 24 }}>Result:</div>
             <div style={{ color: COLORS.eigen1, fontSize: 20 }}>λ₁ = 3, v₁ = [1, 0]</div>
             <div style={{ color: COLORS.eigen2, fontSize: 20 }}>λ₂ = 2, v₂ = [1, -1]</div>

             <div style={{ marginTop: 20, borderTop: '1px solid #555', paddingTop: 20 }}>
                <MatrixDisplay matrix={{a: 1, b: 1, c: 0, d: -1}} label="P" />
                <MatrixDisplay matrix={{a: 3, b: 0, c: 0, d: 2}} label="D" />
             </div>
           </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

const Scene5: React.FC<SceneProps> = ({ progress }) => {
  const opacity = interpolate(progress, [0, 0.2], [0, 1]);
  const slideUp = interpolate(progress, [0, 1], [50, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.background, justifyContent: 'center', alignItems: 'center' }}>
      <div style={{ 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'center', 
        gap: 40, 
        opacity,
        transform: `translateY(${slideUp}px)`
      }}>
        <Latex size={60} color={COLORS.primary}>Why is this useful?</Latex>

        <div style={{ 
          background: 'rgba(255,255,255,0.05)', 
          padding: '40px', 
          borderRadius: '15px', 
          textAlign: 'center',
          border: `1px solid ${COLORS.primary}`
        }}>
          <Latex size={50} color={COLORS.text}>
            Aⁿ = PDⁿP⁻¹
          </Latex>
          <p style={{ color: COLORS.text, fontSize: 24, marginTop: 20 }}>
            Computing powers of diagonal matrices is trivial!
          </p>
        </div>

        <div style={{ display: 'flex', gap: 20, marginTop: 20 }}>
          {['Vibrations', 'PCA', 'Differential Equations', 'Quantum Mechanics'].map((app) => (
            <span key={app} style={{
              background: COLORS.secondary,
              color: '#fff',
              padding: '10px 20px',
              borderRadius: '20px',
              fontSize: 20,
              fontWeight: 'bold'
            }}>
              {app}
            </span>
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// --- Main Component ---

export const EigenvaluesVideo: React.FC = () => {
  const { durationInFrames } = useVideoConfig();

  // Calculate scene durations based on percentages
  const scene1End = Math.floor(durationInFrames * 0.15);
  const scene2End = scene1End + Math.floor(durationInFrames * 0.25);
  const scene3End = scene2End + Math.floor(durationInFrames * 0.30);
  const scene4End = scene3End + Math.floor(durationInFrames * 0.20);
  // Scene 5 takes the rest

  return (
    <AbsoluteFill>
      <Sequence from={0} durationInFrames={scene1End}>
        <Scene1ProgressWrapper />
      </Sequence>

      <Sequence from={scene1End} durationInFrames={scene2End - scene1End}>
        <Scene2ProgressWrapper />
      </Sequence>

      <Sequence from={scene2End} durationInFrames={scene3End - scene2End}>
        <Scene3ProgressWrapper />
      </Sequence>

      <Sequence from={scene3End} durationInFrames={scene4End - scene3End}>
        <Scene4ProgressWrapper />
      </Sequence>

      <Sequence from={scene4End} durationInFrames={durationInFrames - scene4End}>
        <Scene5ProgressWrapper />
      </Sequence>
    </AbsoluteFill>
  );
};

// --- Wrappers to handle local progress for each scene ---
// This ensures animations restart at the beginning of each scene

const Scene1ProgressWrapper: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  // Local duration for this scene is 15% of total
  const localDuration = Math.floor(durationInFrames * 0.15);
  const progress = Math.min(frame / localDuration, 1);
  return <Scene1 progress={progress} />;
};

const Scene2ProgressWrapper: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const startFrame = Math.floor(durationInFrames * 0.15);
  const localDuration = Math.floor(durationInFrames * 0.25);
  const progress = Math.min((frame - startFrame) / localDuration, 1);
  return <Scene2 progress={progress} />;
};

const Scene3ProgressWrapper: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const startFrame = Math.floor(durationInFrames * 0.40); // 15 + 25
  const localDuration = Math.floor(durationInFrames * 0.30);
  const progress = Math.min((frame - startFrame) / localDuration, 1);
  return <Scene3 progress={progress} />;
};

const Scene4ProgressWrapper: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const startFrame = Math.floor(durationInFrames * 0.70); // 15 + 25 + 30
  const localDuration = Math.floor(durationInFrames * 0.20);
  const progress = Math.min((frame - startFrame) / localDuration, 1);
  return <Scene4 progress={progress} />;
};

const Scene5ProgressWrapper: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const startFrame = Math.floor(durationInFrames * 0.90); // 15 + 25 + 30 + 20
  const localDuration = Math.floor(durationInFrames * 0.10);
  const progress = Math.min((frame - startFrame) / localDuration, 1);
  return <Scene5 progress={progress} />;
};

